// Lógica do fluxo "eLabFTW – Insumo do relatório anual" (item 6 do BACKLOG).
// Funções puras: recebem os recursos e experimentos completos (GET /items/{id}, GET /experiments/{id}) e os usuários
// e devolvem o documento Markdown, o resumo que vai para a IA e o pedido de e-mail. Só lê; não altera nada.
// Sigilo: evidência "Restrito ao parceiro" aparece no documento só como contagem e link, sem título; a IA recebe
// apenas dados agregados (sem textos, sem nomes de parceiros, sem títulos de evidências, marcos, desvios ou caderno).

function campos(x) {
  let m = x.metadata_decoded || x.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = {}; }
  }
  return (m && m.extra_fields) || {};
}

function valor(x, nome) {
  const c = campos(x)[nome];
  return c && c.value !== undefined && c.value !== null ? String(c.value).trim() : '';
}

function ligados(x, categorias) {
  const ids = new Map();
  for (const l of [...(x.items_links || []), ...(x.related_items_links || []),
    ...(x.experiments_links || []), ...(x.related_experiments_links || [])]) {
    if (l && categorias.includes(l.category_title)) ids.set(`${l.category_title}:${l.entityid}`, l);
  }
  return [...ids.values()];
}

const ISO = /^\d{4}-\d{2}-\d{2}$/;
const br = (iso) => (iso && ISO.test(iso) ? iso.split('-').reverse().join('/') : '');
const dia = (s) => String(s || '').slice(0, 10);

// Período padrão: o ano civil anterior à data de execução (o relatório de 15/01/2027 cobre 2026).
function periodoDe(cfg, hoje) {
  if (cfg.inicio || cfg.fim) {
    if (!ISO.test(cfg.inicio || '') || !ISO.test(cfg.fim || '') || cfg.inicio > cfg.fim) {
      throw new Error(`Período inválido: início "${cfg.inicio}" e fim "${cfg.fim}" devem estar em AAAA-MM-DD, com início antes do fim.`);
    }
    return { inicio: cfg.inicio, fim: cfg.fim };
  }
  const ano = hoje.getFullYear() - 1;
  return { inicio: `${ano}-01-01`, fim: `${ano}-12-31` };
}

// Texto de uma linha, seguro para Markdown (tabelas e listas).
function md(s) {
  return String(s ?? '').replace(/[\r\n]+/g, ' ').replace(/\|/g, '\\|').replace(/([*_`[\]<>])/g, '\\$1').trim();
}

function montarRelatorio({ recursos, experimentos, usuarios, cfg, hoje }) {
  const per = periodoDe(cfg, hoje);
  const c = cfg.categorias;
  const noPeriodo = (d) => Boolean(d) && d >= per.inicio && d <= per.fim;
  const url = (x) => `${cfg.urlPublica}/${x._tipo === 'exp' ? 'experiments' : 'database'}.php?mode=view&id=${x.id}`;
  const link = (x, texto) => `[${md(texto)}](${url(x)})`;
  const pessoa = new Map((usuarios || []).filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const nomeDe = (id) => { const p = pessoa.get(String(id)); return (p && p.fullname) || ''; };

  const itens = (recursos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'item' }));
  const exps = (experimentos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'exp' }));
  const todos = [...itens, ...exps];

  const dataDe = (x) => {
    if (x.category_title === c.evidencia) return valor(x, cfg.campoDataEvidencia) || dia(x.date) || dia(x.created_at);
    if (x.category_title === c.marco) return valor(x, cfg.campoFimMarco) || dia(x.date) || dia(x.created_at);
    return dia(x.date) || dia(x.created_at);
  };

  const encerradas = [cfg.situacaoConcluido, cfg.situacaoSuspenso];
  const fichas = itens.filter((x) => x.category_title === c.ficha).filter((f) => {
    const inicio = valor(f, cfg.campoInicio) || dia(f.created_at);
    if (inicio && inicio > per.fim) return false;
    if (encerradas.includes(f.status_title) && dia(f.modified_at) < per.inicio) return false;
    return true;
  }).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
  const idsFichas = new Set(fichas.map((f) => String(f.id)));
  const fichasDe = (x) => ligados(x, [c.ficha]).map((l) => String(l.entityid));
  const doProjeto = (f) => todos.filter((x) => x.id !== f.id || x._tipo !== 'item').filter((x) => fichasDe(x).includes(String(f.id)));

  const registros = [c.plano, c.caderno, c.desvio, c.marco, c.evidencia, c.produto];
  const restrita = (x) => valor(x, cfg.campoSigilo) === cfg.sigiloRestrito;
  const publicado = (x) => valor(x, cfg.campoSituacaoProduto) === cfg.produtoPublicado;

  const linhas = [];
  const L = (s = '') => linhas.push(s);
  const projetosIA = [];
  const produtosTodos = [];
  const pontos = [];
  const pi = [];
  const porSituacao = new Map();
  const contagem = Object.fromEntries(registros.map((k) => [k, 0]));
  let restritas = 0;

  const secoes = [];
  fichas.forEach((f, i) => {
    const cod = `P${i + 1}`;
    porSituacao.set(f.status_title, (porSituacao.get(f.status_title) || 0) + 1);
    const ligadosAqui = doProjeto(f);
    const cat = (k) => ligadosAqui.filter((x) => x.category_title === k);
    const doPeriodo = (k) => cat(k).filter((x) => noPeriodo(dataDe(x)));
    const planos = cat(c.plano);
    const marcos = doPeriodo(c.marco).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const desvios = doPeriodo(c.desvio).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const cadernos = doPeriodo(c.caderno);
    const evidencias = doPeriodo(c.evidencia).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
    const produtos = cat(c.produto);
    for (const k of registros) contagem[k] += k === c.produto ? produtos.length : k === c.plano ? planos.length : doPeriodo(k).length;
    const nRestritas = evidencias.filter(restrita).length;
    restritas += nRestritas;

    const s = [];
    s.push(`### ${cod}. ${md(f.title)}`, '');
    s.push(`- Ficha: ${link(f, f.title)} — situação: **${md(f.status_title)}**`);
    const vinculo = valor(f, 'Vínculo');
    const parceiro = valor(f, 'Parceiro');
    s.push(`- Vínculo: ${md(vinculo) || 'não informado'}${parceiro ? `; parceiro ou financiador: ${md(parceiro)}` : ''}`);
    s.push(`- Pesquisador-líder: ${md(valor(f, 'Pesquisador-líder') || nomeDe(f.userid)) || 'não informado'}`);
    if (valor(f, 'Pesquisadores')) s.push(`- Pesquisadores: ${md(valor(f, 'Pesquisadores'))}`);
    if (valor(f, 'Colaboradores e orientador')) s.push(`- Colaboradores e orientador: ${md(valor(f, 'Colaboradores e orientador'))}`);
    const ini = valor(f, cfg.campoInicio);
    const fim = valor(f, cfg.campoTermino);
    s.push(`- Início: ${br(ini) || 'não informado'}; término previsto: ${br(fim) || 'não informado'}`);
    if (planos.length) {
      for (const p of planos) s.push(`- Plano: ${link(p, p.title)} (${md(p.status_title)}); abordagem: ${md(valor(p, 'Abordagem metodológica')) || 'não informada'}`);
    } else {
      s.push('- Plano: **sem plano de pesquisa ligado à ficha**');
    }
    s.push(`- No período: ${cadernos.length} entrada(s) de caderno, ${desvios.length} desvio(s), ${marcos.length} relatório(s) de marco, ${evidencias.length} evidência(s)${nRestritas ? ` (${nRestritas} restrita(s) ao parceiro)` : ''}.`);
    s.push('');
    if (marcos.length) {
      s.push('**Marcos no período**', '');
      marcos.forEach((m, j) => s.push(`- ${cod}-M${j + 1}. ${link(m, m.title)} — ${md(valor(m, 'Situação')) || 'situação não informada'}; período ${br(valor(m, 'Início do período')) || '?'} a ${br(valor(m, cfg.campoFimMarco)) || '?'}`));
      s.push('');
    }
    if (desvios.length) {
      s.push('**Desvios do plano no período**', '');
      desvios.forEach((d, j) => s.push(`- ${cod}-D${j + 1}. ${link(d, d.title)} — aspecto: ${md(valor(d, 'Aspecto alterado')) || 'não informado'}; ${br(dataDe(d))}`));
      s.push('');
    }
    if (produtos.length) {
      s.push('**Produtos**', '');
      produtos.forEach((p, j) => {
        const doi = valor(p, cfg.campoDoi);
        s.push(`- ${cod}-R${j + 1}. ${link(p, p.title)} — ${md(valor(p, 'Tipo de produto')) || 'tipo não informado'}; ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'}${doi ? `; ${md(doi)}` : ''}`);
        produtosTodos.push({ cod: `${cod}-R${j + 1}`, p, f, doi });
        if (publicado(p) && !doi) pontos.push(`${cod}-R${j + 1}. Produto publicado sem DOI ou endereço: ${link(p, p.title)}`);
        if (cfg.tiposPI.includes(valor(p, 'Tipo de produto'))) pi.push(`${cod}-R${j + 1}. ${link(p, p.title)} (${md(valor(p, 'Tipo de produto'))}, ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'})`);
      });
      s.push('');
    }
    if (evidencias.length) {
      s.push('**Evidências no período**', '');
      evidencias.forEach((e) => {
        const quando = br(dataDe(e));
        s.push(restrita(e)
          ? `- ${link(e, 'Evidência restrita ao parceiro')} — ${quando}`
          : `- ${link(e, e.title)} — ${md(valor(e, 'Tipo')) || 'tipo não informado'}; ${md(valor(e, cfg.campoSigilo)) || 'sigilo não informado'}; ${quando}`);
      });
      s.push('');
    }
    const passoPI = (f.steps || []).find((st) => /propriedade intelectual/i.test(st.body || ''));
    if (passoPI) pi.push(`${cod}. ${link(f, f.title)}: avaliação de propriedade intelectual pelo Comitê ${Number(passoPI.finished) ? 'registrada como feita' : 'ainda não marcada na ficha'}`);
    if (fim && fim < dia(hoje.toISOString()) && f.status_title === cfg.situacaoAndamento) pontos.push(`${cod}. Término previsto (${br(fim)}) já passou e o projeto continua "${md(cfg.situacaoAndamento)}": ${link(f, f.title)}`);
    if (!planos.length) pontos.push(`${cod}. Sem plano de pesquisa ligado: ${link(f, f.title)}`);
    secoes.push(s.join('\n'));

    projetosIA.push({
      codigo: cod,
      titulo: f.title,
      situacao: f.status_title,
      vinculo: vinculo || 'não informado',
      inicio: ini || '',
      terminoPrevisto: fim || '',
      abordagem: planos.map((p) => valor(p, 'Abordagem metodológica')).filter(Boolean).join('; '),
      noPeriodo: { cadernos: cadernos.length, desvios: desvios.length, marcos: marcos.length, evidencias: evidencias.length },
      marcos: marcos.map((m, j) => ({ codigo: `${cod}-M${j + 1}`, situacao: valor(m, 'Situação'), inicio: valor(m, 'Início do período'), fim: valor(m, cfg.campoFimMarco) })),
      desvios: desvios.map((d, j) => ({ codigo: `${cod}-D${j + 1}`, aspecto: valor(d, 'Aspecto alterado') })),
      produtos: produtos.map((p, j) => ({ codigo: `${cod}-R${j + 1}`, tipo: valor(p, 'Tipo de produto'), situacao: valor(p, cfg.campoSituacaoProduto), ...(publicado(p) ? { titulo: p.title, doi: valor(p, cfg.campoDoi) } : {}) })),
    });
  });

  // registros do período sem ligação com nenhum projeto
  const soltos = todos.filter((x) => registros.includes(x.category_title) && !fichasDe(x).some((id) => idsFichas.has(id)) && noPeriodo(dataDe(x)));

  const ano = per.inicio.slice(0, 4) === per.fim.slice(0, 4) && per.inicio.endsWith('-01-01') && per.fim.endsWith('-12-31') ? per.inicio.slice(0, 4) : '';
  const rotuloPeriodo = ano || `${br(per.inicio)} a ${br(per.fim)}`;
  const agora = new Date(hoje.getTime() + cfg.fusoHoras * 3600e3).toISOString();
  L(`# Insumo para o relatório anual de PD&I — ${rotuloPeriodo}`);
  L();
  L(`*Gerado em ${br(agora.slice(0, 10))} às ${agora.slice(11, 16)} a partir do eLabFTW do Modal. Período: ${br(per.inicio)} a ${br(per.fim)}. Os links exigem entrada no eLabFTW. Este documento é a base para escrever a seção de PD&I; não é anexado ao relatório.*`);
  L();
  L('## 1. Resumo em números');
  L();
  L('| Indicador | Quantidade |');
  L('|---|---|');
  L(`| Projetos considerados | ${fichas.length} |`);
  for (const [sit, n] of [...porSituacao].sort()) L(`| Projetos ${md(sit).toLowerCase()} | ${n} |`);
  L(`| Entradas de caderno no período | ${contagem[c.caderno]} |`);
  L(`| Desvios do plano no período | ${contagem[c.desvio]} |`);
  L(`| Relatórios de marco no período | ${contagem[c.marco]} |`);
  L(`| Evidências no período | ${contagem[c.evidencia]}${restritas ? ` (${restritas} restrita(s) ao parceiro)` : ''} |`);
  L(`| Produtos ligados aos projetos | ${contagem[c.produto]} (${produtosTodos.filter((x) => publicado(x.p)).length} publicados) |`);
  L(`| Registros do período sem ligação com projeto | ${soltos.length} |`);
  L();
  L('## 2. Texto de contexto (rascunho gerado por IA)');
  L();
  L('> **Rascunho para revisão.** Texto escrito por IA a partir dos dados agregados abaixo, sem conteúdo restrito ao parceiro, sem textos dos registros e sem o campo de parceiro (o título do projeto vai como está). Cada afirmação cita o código do registro (P1, P1-M1, P1-R1...). Confira antes de usar.');
  L();
  L('{{TEXTO_IA}}');
  L();
  L('## 3. Projetos');
  L();
  if (secoes.length) secoes.forEach((s) => { L(s); L(); });
  else { L('Nenhum projeto no período.'); L(); }
  L('## 4. Produtos e DOIs');
  L();
  if (produtosTodos.length) {
    L('| Código | Produto | Tipo | Situação | DOI ou endereço | Projeto |');
    L('|---|---|---|---|---|---|');
    for (const { cod, p, f, doi } of produtosTodos) L(`| ${cod} | ${link(p, p.title)} | ${md(valor(p, 'Tipo de produto'))} | ${md(valor(p, cfg.campoSituacaoProduto))} | ${md(doi)} | ${md(f.title)} |`);
  } else {
    L('Nenhum produto ligado aos projetos.');
  }
  L();
  L('## 5. Propriedade intelectual');
  L();
  if (pi.length) pi.forEach((x) => L(`- ${x}`));
  else L('Nenhum produto de propriedade intelectual nem avaliação registrada.');
  L();
  L('## 6. Pontos de atenção');
  L();
  if (pontos.length || soltos.length) {
    pontos.forEach((x) => L(`- ${x}`));
    if (soltos.length) {
      L(`- ${soltos.length} registro(s) do período sem ligação com a ficha de um projeto:`);
      soltos.forEach((x) => L(`  - ${restrita(x) ? link(x, 'Evidência restrita ao parceiro') : link(x, x.title)} (${md(x.category_title)}, ${md(nomeDe(x.userid)) || 'dono não identificado'})`));
    }
  } else {
    L('Nenhum.');
  }
  L();

  const resumoIA = {
    periodo: { inicio: per.inicio, fim: per.fim },
    totais: {
      projetos: fichas.length,
      projetosPorSituacao: Object.fromEntries(porSituacao),
      cadernos: contagem[c.caderno], desvios: contagem[c.desvio], marcos: contagem[c.marco],
      evidencias: contagem[c.evidencia], produtos: contagem[c.produto],
    },
    projetos: projetosIA,
  };
  return { periodo: per, rotuloPeriodo, markdown: linhas.join('\n'), resumoIA, totais: resumoIA.totais, pontos: pontos.length + soltos.length };
}

function promptIA(resumoIA) {
  return [
    'Você ajuda o Comitê de PD&I do Instituto Modal (instituto de ciência e tecnologia, Brasil) a escrever a seção de PD&I do relatório anual.',
    'Escreva em português do Brasil, em prosa corrida, de um a quatro parágrafos curtos (menos dados, menos texto), um texto de contexto sobre as atividades de pesquisa aplicada do período, com base SOMENTE nos dados JSON abaixo.',
    'Regras:',
    '- Toda afirmação sobre um projeto, marco, desvio ou produto cita o código entre colchetes, por exemplo [P1] ou [P1-R2].',
    '- Use só o que está nos dados. Não invente nem deduza resultados, números, nomes, organizações, parceiros, impactos ou expectativas futuras.',
    '- Não diga que um projeto está no prazo, atrasado ou dentro do cronograma, a menos que um marco traga essa situação. Ausência de marcos ou desvios não significa nada: não a interprete.',
    '- Não qualifique registros (por exemplo, "evidências fundamentais", "produto significativo") nem diga para que servem.',
    '- Não escreva frases genéricas sobre pesquisa, metodologia, boas práticas ou o que um tipo de registro costuma ser. Cada frase deve conter um fato dos dados.',
    '- Não comente a ausência de dados. Se não houve marcos ou desvios, simplesmente não fale deles.',
    '- Não mencione o nome de parceiros ou empresas; o vínculo ("Projeto com parceiro", "Fomento externo") pode ser citado.',
    '- Não use títulos, listas, tabelas nem HTML; só parágrafos de texto simples.',
    '- Tom institucional e sóbrio, sem adjetivos promocionais.',
    '- Quando houver desvios ou marcos com atraso, mencione-os com naturalidade, como parte do processo de pesquisa.',
    '',
    'Dados:',
    JSON.stringify(resumoIA, null, 1),
  ].join('\n');
}

// Junta o texto da IA ao documento. A IA não é confiável: o texto vira parágrafos simples, sem HTML nem Markdown ativo.
function finalizarDocumento(markdown, textoIA) {
  const limpo = String(textoIA || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/^#+\s*/gm, '')
    .replace(/[ \t]+/g, ' ')
    .split(/\n\s*\n/)
    .map((p) => p.replace(/\s*\n\s*/g, ' ').trim())
    .filter(Boolean)
    .join('\n\n');
  const texto = limpo || '*O texto de contexto não foi gerado nesta execução (falha ou resposta vazia da IA). O restante do documento está completo.*';
  return markdown.replace('{{TEXTO_IA}}', () => texto);
}

function pedidoEmail({ rel, usuarios, cfg }) {
  const testador = (usuarios || []).find((u) => u && String(u.userid) === String(cfg.usuarioTesteId));
  if (cfg.modoTeste && !(testador && testador.email)) {
    throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi enviado.`);
  }
  const t = rel.totais;
  const blocos = [
    { tipo: 'paragrafo', texto: `Segue em anexo o insumo para a seção de PD&I do relatório anual (${rel.rotuloPeriodo}), gerado a partir do eLabFTW. É um documento Markdown, com links para os registros (os links exigem entrada no eLabFTW).` },
    { tipo: 'lista', itens: [
      { texto: `${t.projetos} projeto(s) considerado(s)` },
      { texto: `${t.cadernos} entrada(s) de caderno, ${t.desvios} desvio(s) e ${t.marcos} relatório(s) de marco no período` },
      { texto: `${t.evidencias} evidência(s) no período e ${t.produtos} produto(s) ligados aos projetos` },
      { texto: `${rel.pontos} ponto(s) de atenção (seção 6 do documento)` },
    ] },
    { tipo: 'paragrafo', texto: 'A seção 2 traz um texto de contexto escrito por IA, marcado como rascunho: confira cada afirmação pelos códigos citados antes de usar. A IA não recebeu conteúdo restrito ao parceiro, textos dos registros nem o campo de parceiro.' },
  ];
  if (cfg.modoTeste) blocos.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este e-mail iria para ${cfg.para}${cfg.copia ? `, com cópia para ${cfg.copia}` : ''}.` });
  return {
    para: cfg.modoTeste ? testador.email : cfg.para,
    cc: cfg.modoTeste ? '' : cfg.copia,
    nomeRemetente: 'PD&I Modal',
    responderPara: 'pesquisa@modal.org.br',
    assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    etiqueta: 'eLabFTW · Relatório anual',
    titulo: `Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    blocos,
    acaoRotulo: 'Abrir o eLabFTW',
    acaoUrl: cfg.urlPublica,
    rodape: 'Gerado automaticamente a partir do eLabFTW do Modal. Dúvidas: pesquisa@modal.org.br.',
    anexos: 'relatorio',
  };
}

function nomeArquivo(rel) {
  return `insumo-relatorio-pdi-${rel.periodo.inicio}-a-${rel.periodo.fim}.md`;
}


const dados = (nome) => $(nome).all().map((i) => i.json);
const rel = montarRelatorio({
  recursos: dados('Ler recurso completo'),
  experimentos: dados('Ler experimento completo'),
  usuarios: dados('Ler usuários'),
  cfg: $('Configuração').first().json,
  hoje: new Date(),
});
return [{ json: { ...rel, prompt: promptIA(rel.resumoIA) } }];

// Lógica do fluxo "eLabFTW – Insumo do relatório anual" (item 6 do BACKLOG).
// Funções puras: recebem os recursos e experimentos completos (GET /items/{id}, GET /experiments/{id}) e os usuários
// e devolvem o documento Markdown, o resumo que vai para a IA e o pedido de e-mail. Só lê; não altera nada.
// Sigilo: evidência "Restrito ao parceiro" aparece no documento só como contagem e link, sem título; a IA recebe
// apenas dados agregados (sem textos, sem nomes de parceiros, sem títulos de evidências, marcos, desvios ou caderno).

function campos(x) {
  let m = x.metadata_decoded || x.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = {}; }
  }
  return (m && m.extra_fields) || {};
}

function valor(x, nome) {
  const c = campos(x)[nome];
  return c && c.value !== undefined && c.value !== null ? String(c.value).trim() : '';
}

function ligados(x, categorias) {
  const ids = new Map();
  for (const l of [...(x.items_links || []), ...(x.related_items_links || []),
    ...(x.experiments_links || []), ...(x.related_experiments_links || [])]) {
    if (l && categorias.includes(l.category_title)) ids.set(`${l.category_title}:${l.entityid}`, l);
  }
  return [...ids.values()];
}

const ISO = /^\d{4}-\d{2}-\d{2}$/;
const br = (iso) => (iso && ISO.test(iso) ? iso.split('-').reverse().join('/') : '');
const dia = (s) => String(s || '').slice(0, 10);

// Período padrão: o ano civil anterior à data de execução (o relatório de 15/01/2027 cobre 2026).
function periodoDe(cfg, hoje) {
  if (cfg.inicio || cfg.fim) {
    if (!ISO.test(cfg.inicio || '') || !ISO.test(cfg.fim || '') || cfg.inicio > cfg.fim) {
      throw new Error(`Período inválido: início "${cfg.inicio}" e fim "${cfg.fim}" devem estar em AAAA-MM-DD, com início antes do fim.`);
    }
    return { inicio: cfg.inicio, fim: cfg.fim };
  }
  const ano = hoje.getFullYear() - 1;
  return { inicio: `${ano}-01-01`, fim: `${ano}-12-31` };
}

// Texto de uma linha, seguro para Markdown (tabelas e listas).
function md(s) {
  return String(s ?? '').replace(/[\r\n]+/g, ' ').replace(/\|/g, '\\|').replace(/([*_`[\]<>])/g, '\\$1').trim();
}

function montarRelatorio({ recursos, experimentos, usuarios, cfg, hoje }) {
  const per = periodoDe(cfg, hoje);
  const c = cfg.categorias;
  const noPeriodo = (d) => Boolean(d) && d >= per.inicio && d <= per.fim;
  const url = (x) => `${cfg.urlPublica}/${x._tipo === 'exp' ? 'experiments' : 'database'}.php?mode=view&id=${x.id}`;
  const link = (x, texto) => `[${md(texto)}](${url(x)})`;
  const pessoa = new Map((usuarios || []).filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const nomeDe = (id) => { const p = pessoa.get(String(id)); return (p && p.fullname) || ''; };

  const itens = (recursos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'item' }));
  const exps = (experimentos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'exp' }));
  const todos = [...itens, ...exps];

  const dataDe = (x) => {
    if (x.category_title === c.evidencia) return valor(x, cfg.campoDataEvidencia) || dia(x.date) || dia(x.created_at);
    if (x.category_title === c.marco) return valor(x, cfg.campoFimMarco) || dia(x.date) || dia(x.created_at);
    return dia(x.date) || dia(x.created_at);
  };

  const encerradas = [cfg.situacaoConcluido, cfg.situacaoSuspenso];
  const fichas = itens.filter((x) => x.category_title === c.ficha).filter((f) => {
    const inicio = valor(f, cfg.campoInicio) || dia(f.created_at);
    if (inicio && inicio > per.fim) return false;
    if (encerradas.includes(f.status_title) && dia(f.modified_at) < per.inicio) return false;
    return true;
  }).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
  const idsFichas = new Set(fichas.map((f) => String(f.id)));
  const fichasDe = (x) => ligados(x, [c.ficha]).map((l) => String(l.entityid));
  const doProjeto = (f) => todos.filter((x) => x.id !== f.id || x._tipo !== 'item').filter((x) => fichasDe(x).includes(String(f.id)));

  const registros = [c.plano, c.caderno, c.desvio, c.marco, c.evidencia, c.produto];
  const restrita = (x) => valor(x, cfg.campoSigilo) === cfg.sigiloRestrito;
  const publicado = (x) => valor(x, cfg.campoSituacaoProduto) === cfg.produtoPublicado;

  const linhas = [];
  const L = (s = '') => linhas.push(s);
  const projetosIA = [];
  const produtosTodos = [];
  const pontos = [];
  const pi = [];
  const porSituacao = new Map();
  const contagem = Object.fromEntries(registros.map((k) => [k, 0]));
  let restritas = 0;

  const secoes = [];
  fichas.forEach((f, i) => {
    const cod = `P${i + 1}`;
    porSituacao.set(f.status_title, (porSituacao.get(f.status_title) || 0) + 1);
    const ligadosAqui = doProjeto(f);
    const cat = (k) => ligadosAqui.filter((x) => x.category_title === k);
    const doPeriodo = (k) => cat(k).filter((x) => noPeriodo(dataDe(x)));
    const planos = cat(c.plano);
    const marcos = doPeriodo(c.marco).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const desvios = doPeriodo(c.desvio).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const cadernos = doPeriodo(c.caderno);
    const evidencias = doPeriodo(c.evidencia).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
    const produtos = cat(c.produto);
    for (const k of registros) contagem[k] += k === c.produto ? produtos.length : k === c.plano ? planos.length : doPeriodo(k).length;
    const nRestritas = evidencias.filter(restrita).length;
    restritas += nRestritas;

    const s = [];
    s.push(`### ${cod}. ${md(f.title)}`, '');
    s.push(`- Ficha: ${link(f, f.title)} — situação: **${md(f.status_title)}**`);
    const vinculo = valor(f, 'Vínculo');
    const parceiro = valor(f, 'Parceiro');
    s.push(`- Vínculo: ${md(vinculo) || 'não informado'}${parceiro ? `; parceiro ou financiador: ${md(parceiro)}` : ''}`);
    s.push(`- Pesquisador-líder: ${md(valor(f, 'Pesquisador-líder') || nomeDe(f.userid)) || 'não informado'}`);
    if (valor(f, 'Pesquisadores')) s.push(`- Pesquisadores: ${md(valor(f, 'Pesquisadores'))}`);
    if (valor(f, 'Colaboradores e orientador')) s.push(`- Colaboradores e orientador: ${md(valor(f, 'Colaboradores e orientador'))}`);
    const ini = valor(f, cfg.campoInicio);
    const fim = valor(f, cfg.campoTermino);
    s.push(`- Início: ${br(ini) || 'não informado'}; término previsto: ${br(fim) || 'não informado'}`);
    if (planos.length) {
      for (const p of planos) s.push(`- Plano: ${link(p, p.title)} (${md(p.status_title)}); abordagem: ${md(valor(p, 'Abordagem metodológica')) || 'não informada'}`);
    } else {
      s.push('- Plano: **sem plano de pesquisa ligado à ficha**');
    }
    s.push(`- No período: ${cadernos.length} entrada(s) de caderno, ${desvios.length} desvio(s), ${marcos.length} relatório(s) de marco, ${evidencias.length} evidência(s)${nRestritas ? ` (${nRestritas} restrita(s) ao parceiro)` : ''}.`);
    s.push('');
    if (marcos.length) {
      s.push('**Marcos no período**', '');
      marcos.forEach((m, j) => s.push(`- ${cod}-M${j + 1}. ${link(m, m.title)} — ${md(valor(m, 'Situação')) || 'situação não informada'}; período ${br(valor(m, 'Início do período')) || '?'} a ${br(valor(m, cfg.campoFimMarco)) || '?'}`));
      s.push('');
    }
    if (desvios.length) {
      s.push('**Desvios do plano no período**', '');
      desvios.forEach((d, j) => s.push(`- ${cod}-D${j + 1}. ${link(d, d.title)} — aspecto: ${md(valor(d, 'Aspecto alterado')) || 'não informado'}; ${br(dataDe(d))}`));
      s.push('');
    }
    if (produtos.length) {
      s.push('**Produtos**', '');
      produtos.forEach((p, j) => {
        const doi = valor(p, cfg.campoDoi);
        s.push(`- ${cod}-R${j + 1}. ${link(p, p.title)} — ${md(valor(p, 'Tipo de produto')) || 'tipo não informado'}; ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'}${doi ? `; ${md(doi)}` : ''}`);
        produtosTodos.push({ cod: `${cod}-R${j + 1}`, p, f, doi });
        if (publicado(p) && !doi) pontos.push(`${cod}-R${j + 1}. Produto publicado sem DOI ou endereço: ${link(p, p.title)}`);
        if (cfg.tiposPI.includes(valor(p, 'Tipo de produto'))) pi.push(`${cod}-R${j + 1}. ${link(p, p.title)} (${md(valor(p, 'Tipo de produto'))}, ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'})`);
      });
      s.push('');
    }
    if (evidencias.length) {
      s.push('**Evidências no período**', '');
      evidencias.forEach((e) => {
        const quando = br(dataDe(e));
        s.push(restrita(e)
          ? `- ${link(e, 'Evidência restrita ao parceiro')} — ${quando}`
          : `- ${link(e, e.title)} — ${md(valor(e, 'Tipo')) || 'tipo não informado'}; ${md(valor(e, cfg.campoSigilo)) || 'sigilo não informado'}; ${quando}`);
      });
      s.push('');
    }
    const passoPI = (f.steps || []).find((st) => /propriedade intelectual/i.test(st.body || ''));
    if (passoPI) pi.push(`${cod}. ${link(f, f.title)}: avaliação de propriedade intelectual pelo Comitê ${Number(passoPI.finished) ? 'registrada como feita' : 'ainda não marcada na ficha'}`);
    if (fim && fim < dia(hoje.toISOString()) && f.status_title === cfg.situacaoAndamento) pontos.push(`${cod}. Término previsto (${br(fim)}) já passou e o projeto continua "${md(cfg.situacaoAndamento)}": ${link(f, f.title)}`);
    if (!planos.length) pontos.push(`${cod}. Sem plano de pesquisa ligado: ${link(f, f.title)}`);
    secoes.push(s.join('\n'));

    projetosIA.push({
      codigo: cod,
      titulo: f.title,
      situacao: f.status_title,
      vinculo: vinculo || 'não informado',
      inicio: ini || '',
      terminoPrevisto: fim || '',
      abordagem: planos.map((p) => valor(p, 'Abordagem metodológica')).filter(Boolean).join('; '),
      noPeriodo: { cadernos: cadernos.length, desvios: desvios.length, marcos: marcos.length, evidencias: evidencias.length },
      marcos: marcos.map((m, j) => ({ codigo: `${cod}-M${j + 1}`, situacao: valor(m, 'Situação'), inicio: valor(m, 'Início do período'), fim: valor(m, cfg.campoFimMarco) })),
      desvios: desvios.map((d, j) => ({ codigo: `${cod}-D${j + 1}`, aspecto: valor(d, 'Aspecto alterado') })),
      produtos: produtos.map((p, j) => ({ codigo: `${cod}-R${j + 1}`, tipo: valor(p, 'Tipo de produto'), situacao: valor(p, cfg.campoSituacaoProduto), ...(publicado(p) ? { titulo: p.title, doi: valor(p, cfg.campoDoi) } : {}) })),
    });
  });

  // registros do período sem ligação com nenhum projeto
  const soltos = todos.filter((x) => registros.includes(x.category_title) && !fichasDe(x).some((id) => idsFichas.has(id)) && noPeriodo(dataDe(x)));

  const ano = per.inicio.slice(0, 4) === per.fim.slice(0, 4) && per.inicio.endsWith('-01-01') && per.fim.endsWith('-12-31') ? per.inicio.slice(0, 4) : '';
  const rotuloPeriodo = ano || `${br(per.inicio)} a ${br(per.fim)}`;
  const agora = new Date(hoje.getTime() + cfg.fusoHoras * 3600e3).toISOString();
  L(`# Insumo para o relatório anual de PD&I — ${rotuloPeriodo}`);
  L();
  L(`*Gerado em ${br(agora.slice(0, 10))} às ${agora.slice(11, 16)} a partir do eLabFTW do Modal. Período: ${br(per.inicio)} a ${br(per.fim)}. Os links exigem entrada no eLabFTW. Este documento é a base para escrever a seção de PD&I; não é anexado ao relatório.*`);
  L();
  L('## 1. Resumo em números');
  L();
  L('| Indicador | Quantidade |');
  L('|---|---|');
  L(`| Projetos considerados | ${fichas.length} |`);
  for (const [sit, n] of [...porSituacao].sort()) L(`| Projetos ${md(sit).toLowerCase()} | ${n} |`);
  L(`| Entradas de caderno no período | ${contagem[c.caderno]} |`);
  L(`| Desvios do plano no período | ${contagem[c.desvio]} |`);
  L(`| Relatórios de marco no período | ${contagem[c.marco]} |`);
  L(`| Evidências no período | ${contagem[c.evidencia]}${restritas ? ` (${restritas} restrita(s) ao parceiro)` : ''} |`);
  L(`| Produtos ligados aos projetos | ${contagem[c.produto]} (${produtosTodos.filter((x) => publicado(x.p)).length} publicados) |`);
  L(`| Registros do período sem ligação com projeto | ${soltos.length} |`);
  L();
  L('## 2. Texto de contexto (rascunho gerado por IA)');
  L();
  L('> **Rascunho para revisão.** Texto escrito por IA a partir dos dados agregados abaixo, sem conteúdo restrito ao parceiro, sem textos dos registros e sem o campo de parceiro (o título do projeto vai como está). Cada afirmação cita o código do registro (P1, P1-M1, P1-R1...). Confira antes de usar.');
  L();
  L('{{TEXTO_IA}}');
  L();
  L('## 3. Projetos');
  L();
  if (secoes.length) secoes.forEach((s) => { L(s); L(); });
  else { L('Nenhum projeto no período.'); L(); }
  L('## 4. Produtos e DOIs');
  L();
  if (produtosTodos.length) {
    L('| Código | Produto | Tipo | Situação | DOI ou endereço | Projeto |');
    L('|---|---|---|---|---|---|');
    for (const { cod, p, f, doi } of produtosTodos) L(`| ${cod} | ${link(p, p.title)} | ${md(valor(p, 'Tipo de produto'))} | ${md(valor(p, cfg.campoSituacaoProduto))} | ${md(doi)} | ${md(f.title)} |`);
  } else {
    L('Nenhum produto ligado aos projetos.');
  }
  L();
  L('## 5. Propriedade intelectual');
  L();
  if (pi.length) pi.forEach((x) => L(`- ${x}`));
  else L('Nenhum produto de propriedade intelectual nem avaliação registrada.');
  L();
  L('## 6. Pontos de atenção');
  L();
  if (pontos.length || soltos.length) {
    pontos.forEach((x) => L(`- ${x}`));
    if (soltos.length) {
      L(`- ${soltos.length} registro(s) do período sem ligação com a ficha de um projeto:`);
      soltos.forEach((x) => L(`  - ${restrita(x) ? link(x, 'Evidência restrita ao parceiro') : link(x, x.title)} (${md(x.category_title)}, ${md(nomeDe(x.userid)) || 'dono não identificado'})`));
    }
  } else {
    L('Nenhum.');
  }
  L();

  const resumoIA = {
    periodo: { inicio: per.inicio, fim: per.fim },
    totais: {
      projetos: fichas.length,
      projetosPorSituacao: Object.fromEntries(porSituacao),
      cadernos: contagem[c.caderno], desvios: contagem[c.desvio], marcos: contagem[c.marco],
      evidencias: contagem[c.evidencia], produtos: contagem[c.produto],
    },
    projetos: projetosIA,
  };
  return { periodo: per, rotuloPeriodo, markdown: linhas.join('\n'), resumoIA, totais: resumoIA.totais, pontos: pontos.length + soltos.length };
}

function promptIA(resumoIA) {
  return [
    'Você ajuda o Comitê de PD&I do Instituto Modal (instituto de ciência e tecnologia, Brasil) a escrever a seção de PD&I do relatório anual.',
    'Escreva em português do Brasil, em prosa corrida, de um a quatro parágrafos curtos (menos dados, menos texto), um texto de contexto sobre as atividades de pesquisa aplicada do período, com base SOMENTE nos dados JSON abaixo.',
    'Regras:',
    '- Toda afirmação sobre um projeto, marco, desvio ou produto cita o código entre colchetes, por exemplo [P1] ou [P1-R2].',
    '- Use só o que está nos dados. Não invente nem deduza resultados, números, nomes, organizações, parceiros, impactos ou expectativas futuras.',
    '- Não diga que um projeto está no prazo, atrasado ou dentro do cronograma, a menos que um marco traga essa situação. Ausência de marcos ou desvios não significa nada: não a interprete.',
    '- Não qualifique registros (por exemplo, "evidências fundamentais", "produto significativo") nem diga para que servem.',
    '- Não escreva frases genéricas sobre pesquisa, metodologia, boas práticas ou o que um tipo de registro costuma ser. Cada frase deve conter um fato dos dados.',
    '- Não comente a ausência de dados. Se não houve marcos ou desvios, simplesmente não fale deles.',
    '- Não mencione o nome de parceiros ou empresas; o vínculo ("Projeto com parceiro", "Fomento externo") pode ser citado.',
    '- Não use títulos, listas, tabelas nem HTML; só parágrafos de texto simples.',
    '- Tom institucional e sóbrio, sem adjetivos promocionais.',
    '- Quando houver desvios ou marcos com atraso, mencione-os com naturalidade, como parte do processo de pesquisa.',
    '',
    'Dados:',
    JSON.stringify(resumoIA, null, 1),
  ].join('\n');
}

// Junta o texto da IA ao documento. A IA não é confiável: o texto vira parágrafos simples, sem HTML nem Markdown ativo.
function finalizarDocumento(markdown, textoIA) {
  const limpo = String(textoIA || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/^#+\s*/gm, '')
    .replace(/[ \t]+/g, ' ')
    .split(/\n\s*\n/)
    .map((p) => p.replace(/\s*\n\s*/g, ' ').trim())
    .filter(Boolean)
    .join('\n\n');
  const texto = limpo || '*O texto de contexto não foi gerado nesta execução (falha ou resposta vazia da IA). O restante do documento está completo.*';
  return markdown.replace('{{TEXTO_IA}}', () => texto);
}

function pedidoEmail({ rel, usuarios, cfg }) {
  const testador = (usuarios || []).find((u) => u && String(u.userid) === String(cfg.usuarioTesteId));
  if (cfg.modoTeste && !(testador && testador.email)) {
    throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi enviado.`);
  }
  const t = rel.totais;
  const blocos = [
    { tipo: 'paragrafo', texto: `Segue em anexo o insumo para a seção de PD&I do relatório anual (${rel.rotuloPeriodo}), gerado a partir do eLabFTW. É um documento Markdown, com links para os registros (os links exigem entrada no eLabFTW).` },
    { tipo: 'lista', itens: [
      { texto: `${t.projetos} projeto(s) considerado(s)` },
      { texto: `${t.cadernos} entrada(s) de caderno, ${t.desvios} desvio(s) e ${t.marcos} relatório(s) de marco no período` },
      { texto: `${t.evidencias} evidência(s) no período e ${t.produtos} produto(s) ligados aos projetos` },
      { texto: `${rel.pontos} ponto(s) de atenção (seção 6 do documento)` },
    ] },
    { tipo: 'paragrafo', texto: 'A seção 2 traz um texto de contexto escrito por IA, marcado como rascunho: confira cada afirmação pelos códigos citados antes de usar. A IA não recebeu conteúdo restrito ao parceiro, textos dos registros nem o campo de parceiro.' },
  ];
  if (cfg.modoTeste) blocos.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este e-mail iria para ${cfg.para}${cfg.copia ? `, com cópia para ${cfg.copia}` : ''}.` });
  return {
    para: cfg.modoTeste ? testador.email : cfg.para,
    cc: cfg.modoTeste ? '' : cfg.copia,
    nomeRemetente: 'PD&I Modal',
    responderPara: 'pesquisa@modal.org.br',
    assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    etiqueta: 'eLabFTW · Relatório anual',
    titulo: `Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    blocos,
    acaoRotulo: 'Abrir o eLabFTW',
    acaoUrl: cfg.urlPublica,
    rodape: 'Gerado automaticamente a partir do eLabFTW do Modal. Dúvidas: pesquisa@modal.org.br.',
    anexos: 'relatorio',
  };
}

function nomeArquivo(rel) {
  return `insumo-relatorio-pdi-${rel.periodo.inicio}-a-${rel.periodo.fim}.md`;
}


const cfg = $('Configuração').first().json;
const rel = $('Montar documento').first().json;
const ia = $input.first().json;
const markdown = finalizarDocumento(rel.markdown, ia && typeof ia.text === 'string' ? ia.text : '');
const pedido = pedidoEmail({ rel, usuarios: $('Ler usuários').all().map((i) => i.json), cfg });
const arquivo = await this.helpers.prepareBinaryData(Buffer.from(markdown, 'utf8'), nomeArquivo(rel), 'text/markdown');
return [{ json: pedido, binary: { relatorio: arquivo } }];

// Lógica do fluxo "eLabFTW – Insumo do relatório anual" (item 6 do BACKLOG).
// Funções puras: recebem os recursos e experimentos completos (GET /items/{id}, GET /experiments/{id}) e os usuários
// e devolvem o documento Markdown, o resumo que vai para a IA e o pedido de e-mail. Só lê; não altera nada.
// Sigilo: evidência "Restrito ao parceiro" aparece no documento só como contagem e link, sem título; a IA recebe
// apenas dados agregados (sem textos, sem nomes de parceiros, sem títulos de evidências, marcos, desvios ou caderno).

function campos(x) {
  let m = x.metadata_decoded || x.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = {}; }
  }
  return (m && m.extra_fields) || {};
}

function valor(x, nome) {
  const c = campos(x)[nome];
  return c && c.value !== undefined && c.value !== null ? String(c.value).trim() : '';
}

function ligados(x, categorias) {
  const ids = new Map();
  for (const l of [...(x.items_links || []), ...(x.related_items_links || []),
    ...(x.experiments_links || []), ...(x.related_experiments_links || [])]) {
    if (l && categorias.includes(l.category_title)) ids.set(`${l.category_title}:${l.entityid}`, l);
  }
  return [...ids.values()];
}

const ISO = /^\d{4}-\d{2}-\d{2}$/;
const br = (iso) => (iso && ISO.test(iso) ? iso.split('-').reverse().join('/') : '');
const dia = (s) => String(s || '').slice(0, 10);

// Período padrão: o ano civil anterior à data de execução (o relatório de 15/01/2027 cobre 2026).
function periodoDe(cfg, hoje) {
  if (cfg.inicio || cfg.fim) {
    if (!ISO.test(cfg.inicio || '') || !ISO.test(cfg.fim || '') || cfg.inicio > cfg.fim) {
      throw new Error(`Período inválido: início "${cfg.inicio}" e fim "${cfg.fim}" devem estar em AAAA-MM-DD, com início antes do fim.`);
    }
    return { inicio: cfg.inicio, fim: cfg.fim };
  }
  const ano = hoje.getFullYear() - 1;
  return { inicio: `${ano}-01-01`, fim: `${ano}-12-31` };
}

// Texto de uma linha, seguro para Markdown (tabelas e listas).
function md(s) {
  return String(s ?? '').replace(/[\r\n]+/g, ' ').replace(/\|/g, '\\|').replace(/([*_`[\]<>])/g, '\\$1').trim();
}

function montarRelatorio({ recursos, experimentos, usuarios, cfg, hoje }) {
  const per = periodoDe(cfg, hoje);
  const c = cfg.categorias;
  const noPeriodo = (d) => Boolean(d) && d >= per.inicio && d <= per.fim;
  const url = (x) => `${cfg.urlPublica}/${x._tipo === 'exp' ? 'experiments' : 'database'}.php?mode=view&id=${x.id}`;
  const link = (x, texto) => `[${md(texto)}](${url(x)})`;
  const pessoa = new Map((usuarios || []).filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const nomeDe = (id) => { const p = pessoa.get(String(id)); return (p && p.fullname) || ''; };

  const itens = (recursos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'item' }));
  const exps = (experimentos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'exp' }));
  const todos = [...itens, ...exps];

  const dataDe = (x) => {
    if (x.category_title === c.evidencia) return valor(x, cfg.campoDataEvidencia) || dia(x.date) || dia(x.created_at);
    if (x.category_title === c.marco) return valor(x, cfg.campoFimMarco) || dia(x.date) || dia(x.created_at);
    return dia(x.date) || dia(x.created_at);
  };

  const encerradas = [cfg.situacaoConcluido, cfg.situacaoSuspenso];
  const fichas = itens.filter((x) => x.category_title === c.ficha).filter((f) => {
    const inicio = valor(f, cfg.campoInicio) || dia(f.created_at);
    if (inicio && inicio > per.fim) return false;
    if (encerradas.includes(f.status_title) && dia(f.modified_at) < per.inicio) return false;
    return true;
  }).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
  const idsFichas = new Set(fichas.map((f) => String(f.id)));
  const fichasDe = (x) => ligados(x, [c.ficha]).map((l) => String(l.entityid));
  const doProjeto = (f) => todos.filter((x) => x.id !== f.id || x._tipo !== 'item').filter((x) => fichasDe(x).includes(String(f.id)));

  const registros = [c.plano, c.caderno, c.desvio, c.marco, c.evidencia, c.produto];
  const restrita = (x) => valor(x, cfg.campoSigilo) === cfg.sigiloRestrito;
  const publicado = (x) => valor(x, cfg.campoSituacaoProduto) === cfg.produtoPublicado;

  const linhas = [];
  const L = (s = '') => linhas.push(s);
  const projetosIA = [];
  const produtosTodos = [];
  const pontos = [];
  const pi = [];
  const porSituacao = new Map();
  const contagem = Object.fromEntries(registros.map((k) => [k, 0]));
  let restritas = 0;

  const secoes = [];
  fichas.forEach((f, i) => {
    const cod = `P${i + 1}`;
    porSituacao.set(f.status_title, (porSituacao.get(f.status_title) || 0) + 1);
    const ligadosAqui = doProjeto(f);
    const cat = (k) => ligadosAqui.filter((x) => x.category_title === k);
    const doPeriodo = (k) => cat(k).filter((x) => noPeriodo(dataDe(x)));
    const planos = cat(c.plano);
    const marcos = doPeriodo(c.marco).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const desvios = doPeriodo(c.desvio).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const cadernos = doPeriodo(c.caderno);
    const evidencias = doPeriodo(c.evidencia).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
    const produtos = cat(c.produto);
    for (const k of registros) contagem[k] += k === c.produto ? produtos.length : k === c.plano ? planos.length : doPeriodo(k).length;
    const nRestritas = evidencias.filter(restrita).length;
    restritas += nRestritas;

    const s = [];
    s.push(`### ${cod}. ${md(f.title)}`, '');
    s.push(`- Ficha: ${link(f, f.title)} — situação: **${md(f.status_title)}**`);
    const vinculo = valor(f, 'Vínculo');
    const parceiro = valor(f, 'Parceiro');
    s.push(`- Vínculo: ${md(vinculo) || 'não informado'}${parceiro ? `; parceiro ou financiador: ${md(parceiro)}` : ''}`);
    s.push(`- Pesquisador-líder: ${md(valor(f, 'Pesquisador-líder') || nomeDe(f.userid)) || 'não informado'}`);
    if (valor(f, 'Pesquisadores')) s.push(`- Pesquisadores: ${md(valor(f, 'Pesquisadores'))}`);
    if (valor(f, 'Colaboradores e orientador')) s.push(`- Colaboradores e orientador: ${md(valor(f, 'Colaboradores e orientador'))}`);
    const ini = valor(f, cfg.campoInicio);
    const fim = valor(f, cfg.campoTermino);
    s.push(`- Início: ${br(ini) || 'não informado'}; término previsto: ${br(fim) || 'não informado'}`);
    if (planos.length) {
      for (const p of planos) s.push(`- Plano: ${link(p, p.title)} (${md(p.status_title)}); abordagem: ${md(valor(p, 'Abordagem metodológica')) || 'não informada'}`);
    } else {
      s.push('- Plano: **sem plano de pesquisa ligado à ficha**');
    }
    s.push(`- No período: ${cadernos.length} entrada(s) de caderno, ${desvios.length} desvio(s), ${marcos.length} relatório(s) de marco, ${evidencias.length} evidência(s)${nRestritas ? ` (${nRestritas} restrita(s) ao parceiro)` : ''}.`);
    s.push('');
    if (marcos.length) {
      s.push('**Marcos no período**', '');
      marcos.forEach((m, j) => s.push(`- ${cod}-M${j + 1}. ${link(m, m.title)} — ${md(valor(m, 'Situação')) || 'situação não informada'}; período ${br(valor(m, 'Início do período')) || '?'} a ${br(valor(m, cfg.campoFimMarco)) || '?'}`));
      s.push('');
    }
    if (desvios.length) {
      s.push('**Desvios do plano no período**', '');
      desvios.forEach((d, j) => s.push(`- ${cod}-D${j + 1}. ${link(d, d.title)} — aspecto: ${md(valor(d, 'Aspecto alterado')) || 'não informado'}; ${br(dataDe(d))}`));
      s.push('');
    }
    if (produtos.length) {
      s.push('**Produtos**', '');
      produtos.forEach((p, j) => {
        const doi = valor(p, cfg.campoDoi);
        s.push(`- ${cod}-R${j + 1}. ${link(p, p.title)} — ${md(valor(p, 'Tipo de produto')) || 'tipo não informado'}; ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'}${doi ? `; ${md(doi)}` : ''}`);
        produtosTodos.push({ cod: `${cod}-R${j + 1}`, p, f, doi });
        if (publicado(p) && !doi) pontos.push(`${cod}-R${j + 1}. Produto publicado sem DOI ou endereço: ${link(p, p.title)}`);
        if (cfg.tiposPI.includes(valor(p, 'Tipo de produto'))) pi.push(`${cod}-R${j + 1}. ${link(p, p.title)} (${md(valor(p, 'Tipo de produto'))}, ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'})`);
      });
      s.push('');
    }
    if (evidencias.length) {
      s.push('**Evidências no período**', '');
      evidencias.forEach((e) => {
        const quando = br(dataDe(e));
        s.push(restrita(e)
          ? `- ${link(e, 'Evidência restrita ao parceiro')} — ${quando}`
          : `- ${link(e, e.title)} — ${md(valor(e, 'Tipo')) || 'tipo não informado'}; ${md(valor(e, cfg.campoSigilo)) || 'sigilo não informado'}; ${quando}`);
      });
      s.push('');
    }
    const passoPI = (f.steps || []).find((st) => /propriedade intelectual/i.test(st.body || ''));
    if (passoPI) pi.push(`${cod}. ${link(f, f.title)}: avaliação de propriedade intelectual pelo Comitê ${Number(passoPI.finished) ? 'registrada como feita' : 'ainda não marcada na ficha'}`);
    if (fim && fim < dia(hoje.toISOString()) && f.status_title === cfg.situacaoAndamento) pontos.push(`${cod}. Término previsto (${br(fim)}) já passou e o projeto continua "${md(cfg.situacaoAndamento)}": ${link(f, f.title)}`);
    if (!planos.length) pontos.push(`${cod}. Sem plano de pesquisa ligado: ${link(f, f.title)}`);
    secoes.push(s.join('\n'));

    projetosIA.push({
      codigo: cod,
      titulo: f.title,
      situacao: f.status_title,
      vinculo: vinculo || 'não informado',
      inicio: ini || '',
      terminoPrevisto: fim || '',
      abordagem: planos.map((p) => valor(p, 'Abordagem metodológica')).filter(Boolean).join('; '),
      noPeriodo: { cadernos: cadernos.length, desvios: desvios.length, marcos: marcos.length, evidencias: evidencias.length },
      marcos: marcos.map((m, j) => ({ codigo: `${cod}-M${j + 1}`, situacao: valor(m, 'Situação'), inicio: valor(m, 'Início do período'), fim: valor(m, cfg.campoFimMarco) })),
      desvios: desvios.map((d, j) => ({ codigo: `${cod}-D${j + 1}`, aspecto: valor(d, 'Aspecto alterado') })),
      produtos: produtos.map((p, j) => ({ codigo: `${cod}-R${j + 1}`, tipo: valor(p, 'Tipo de produto'), situacao: valor(p, cfg.campoSituacaoProduto), ...(publicado(p) ? { titulo: p.title, doi: valor(p, cfg.campoDoi) } : {}) })),
    });
  });

  // registros do período sem ligação com nenhum projeto
  const soltos = todos.filter((x) => registros.includes(x.category_title) && !fichasDe(x).some((id) => idsFichas.has(id)) && noPeriodo(dataDe(x)));

  const ano = per.inicio.slice(0, 4) === per.fim.slice(0, 4) && per.inicio.endsWith('-01-01') && per.fim.endsWith('-12-31') ? per.inicio.slice(0, 4) : '';
  const rotuloPeriodo = ano || `${br(per.inicio)} a ${br(per.fim)}`;
  const agora = new Date(hoje.getTime() + cfg.fusoHoras * 3600e3).toISOString();
  L(`# Insumo para o relatório anual de PD&I — ${rotuloPeriodo}`);
  L();
  L(`*Gerado em ${br(agora.slice(0, 10))} às ${agora.slice(11, 16)} a partir do eLabFTW do Modal. Período: ${br(per.inicio)} a ${br(per.fim)}. Os links exigem entrada no eLabFTW. Este documento é a base para escrever a seção de PD&I; não é anexado ao relatório.*`);
  L();
  L('## 1. Resumo em números');
  L();
  L('| Indicador | Quantidade |');
  L('|---|---|');
  L(`| Projetos considerados | ${fichas.length} |`);
  for (const [sit, n] of [...porSituacao].sort()) L(`| Projetos ${md(sit).toLowerCase()} | ${n} |`);
  L(`| Entradas de caderno no período | ${contagem[c.caderno]} |`);
  L(`| Desvios do plano no período | ${contagem[c.desvio]} |`);
  L(`| Relatórios de marco no período | ${contagem[c.marco]} |`);
  L(`| Evidências no período | ${contagem[c.evidencia]}${restritas ? ` (${restritas} restrita(s) ao parceiro)` : ''} |`);
  L(`| Produtos ligados aos projetos | ${contagem[c.produto]} (${produtosTodos.filter((x) => publicado(x.p)).length} publicados) |`);
  L(`| Registros do período sem ligação com projeto | ${soltos.length} |`);
  L();
  L('## 2. Texto de contexto (rascunho gerado por IA)');
  L();
  L('> **Rascunho para revisão.** Texto escrito por IA a partir dos dados agregados abaixo, sem conteúdo restrito ao parceiro, sem textos dos registros e sem o campo de parceiro (o título do projeto vai como está). Cada afirmação cita o código do registro (P1, P1-M1, P1-R1...). Confira antes de usar.');
  L();
  L('{{TEXTO_IA}}');
  L();
  L('## 3. Projetos');
  L();
  if (secoes.length) secoes.forEach((s) => { L(s); L(); });
  else { L('Nenhum projeto no período.'); L(); }
  L('## 4. Produtos e DOIs');
  L();
  if (produtosTodos.length) {
    L('| Código | Produto | Tipo | Situação | DOI ou endereço | Projeto |');
    L('|---|---|---|---|---|---|');
    for (const { cod, p, f, doi } of produtosTodos) L(`| ${cod} | ${link(p, p.title)} | ${md(valor(p, 'Tipo de produto'))} | ${md(valor(p, cfg.campoSituacaoProduto))} | ${md(doi)} | ${md(f.title)} |`);
  } else {
    L('Nenhum produto ligado aos projetos.');
  }
  L();
  L('## 5. Propriedade intelectual');
  L();
  if (pi.length) pi.forEach((x) => L(`- ${x}`));
  else L('Nenhum produto de propriedade intelectual nem avaliação registrada.');
  L();
  L('## 6. Pontos de atenção');
  L();
  if (pontos.length || soltos.length) {
    pontos.forEach((x) => L(`- ${x}`));
    if (soltos.length) {
      L(`- ${soltos.length} registro(s) do período sem ligação com a ficha de um projeto:`);
      soltos.forEach((x) => L(`  - ${restrita(x) ? link(x, 'Evidência restrita ao parceiro') : link(x, x.title)} (${md(x.category_title)}, ${md(nomeDe(x.userid)) || 'dono não identificado'})`));
    }
  } else {
    L('Nenhum.');
  }
  L();

  const resumoIA = {
    periodo: { inicio: per.inicio, fim: per.fim },
    totais: {
      projetos: fichas.length,
      projetosPorSituacao: Object.fromEntries(porSituacao),
      cadernos: contagem[c.caderno], desvios: contagem[c.desvio], marcos: contagem[c.marco],
      evidencias: contagem[c.evidencia], produtos: contagem[c.produto],
    },
    projetos: projetosIA,
  };
  return { periodo: per, rotuloPeriodo, markdown: linhas.join('\n'), resumoIA, totais: resumoIA.totais, pontos: pontos.length + soltos.length };
}

function promptIA(resumoIA) {
  return [
    'Você ajuda o Comitê de PD&I do Instituto Modal (instituto de ciência e tecnologia, Brasil) a escrever a seção de PD&I do relatório anual.',
    'Escreva em português do Brasil, em prosa corrida, de um a quatro parágrafos curtos (menos dados, menos texto), um texto de contexto sobre as atividades de pesquisa aplicada do período, com base SOMENTE nos dados JSON abaixo.',
    'Regras:',
    '- Toda afirmação sobre um projeto, marco, desvio ou produto cita o código entre colchetes, por exemplo [P1] ou [P1-R2].',
    '- Use só o que está nos dados. Não invente nem deduza resultados, números, nomes, organizações, parceiros, impactos ou expectativas futuras.',
    '- Não diga que um projeto está no prazo, atrasado ou dentro do cronograma, a menos que um marco traga essa situação. Ausência de marcos ou desvios não significa nada: não a interprete.',
    '- Não qualifique registros (por exemplo, "evidências fundamentais", "produto significativo") nem diga para que servem.',
    '- Não escreva frases genéricas sobre pesquisa, metodologia, boas práticas ou o que um tipo de registro costuma ser. Cada frase deve conter um fato dos dados.',
    '- Não comente a ausência de dados. Se não houve marcos ou desvios, simplesmente não fale deles.',
    '- Não mencione o nome de parceiros ou empresas; o vínculo ("Projeto com parceiro", "Fomento externo") pode ser citado.',
    '- Não use títulos, listas, tabelas nem HTML; só parágrafos de texto simples.',
    '- Tom institucional e sóbrio, sem adjetivos promocionais.',
    '- Quando houver desvios ou marcos com atraso, mencione-os com naturalidade, como parte do processo de pesquisa.',
    '',
    'Dados:',
    JSON.stringify(resumoIA, null, 1),
  ].join('\n');
}

// Junta o texto da IA ao documento. A IA não é confiável: o texto vira parágrafos simples, sem HTML nem Markdown ativo.
function finalizarDocumento(markdown, textoIA) {
  const limpo = String(textoIA || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/^#+\s*/gm, '')
    .replace(/[ \t]+/g, ' ')
    .split(/\n\s*\n/)
    .map((p) => p.replace(/\s*\n\s*/g, ' ').trim())
    .filter(Boolean)
    .join('\n\n');
  const texto = limpo || '*O texto de contexto não foi gerado nesta execução (falha ou resposta vazia da IA). O restante do documento está completo.*';
  return markdown.replace('{{TEXTO_IA}}', () => texto);
}

function pedidoEmail({ rel, usuarios, cfg }) {
  const testador = (usuarios || []).find((u) => u && String(u.userid) === String(cfg.usuarioTesteId));
  if (cfg.modoTeste && !(testador && testador.email)) {
    throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi enviado.`);
  }
  const t = rel.totais;
  const blocos = [
    { tipo: 'paragrafo', texto: `Segue em anexo o insumo para a seção de PD&I do relatório anual (${rel.rotuloPeriodo}), gerado a partir do eLabFTW. É um documento Markdown, com links para os registros (os links exigem entrada no eLabFTW).` },
    { tipo: 'lista', itens: [
      { texto: `${t.projetos} projeto(s) considerado(s)` },
      { texto: `${t.cadernos} entrada(s) de caderno, ${t.desvios} desvio(s) e ${t.marcos} relatório(s) de marco no período` },
      { texto: `${t.evidencias} evidência(s) no período e ${t.produtos} produto(s) ligados aos projetos` },
      { texto: `${rel.pontos} ponto(s) de atenção (seção 6 do documento)` },
    ] },
    { tipo: 'paragrafo', texto: 'A seção 2 traz um texto de contexto escrito por IA, marcado como rascunho: confira cada afirmação pelos códigos citados antes de usar. A IA não recebeu conteúdo restrito ao parceiro, textos dos registros nem o campo de parceiro.' },
  ];
  if (cfg.modoTeste) blocos.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este e-mail iria para ${cfg.para}${cfg.copia ? `, com cópia para ${cfg.copia}` : ''}.` });
  return {
    para: cfg.modoTeste ? testador.email : cfg.para,
    cc: cfg.modoTeste ? '' : cfg.copia,
    nomeRemetente: 'PD&I Modal',
    responderPara: 'pesquisa@modal.org.br',
    assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    etiqueta: 'eLabFTW · Relatório anual',
    titulo: `Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    blocos,
    acaoRotulo: 'Abrir o eLabFTW',
    acaoUrl: cfg.urlPublica,
    rodape: 'Gerado automaticamente a partir do eLabFTW do Modal. Dúvidas: pesquisa@modal.org.br.',
    anexos: 'relatorio',
  };
}

function nomeArquivo(rel) {
  return `insumo-relatorio-pdi-${rel.periodo.inicio}-a-${rel.periodo.fim}.md`;
}


const dados = (nome) => $(nome).all().map((i) => i.json);
const rel = montarRelatorio({
  recursos: dados('Ler recurso completo'),
  experimentos: dados('Ler experimento completo'),
  usuarios: dados('Ler usuários'),
  cfg: $('Configuração').first().json,
  hoje: new Date(),
});
return [{ json: { ...rel, prompt: promptIA(rel.resumoIA) } }];

// Lógica do fluxo "eLabFTW – Insumo do relatório anual" (item 6 do BACKLOG).
// Funções puras: recebem os recursos e experimentos completos (GET /items/{id}, GET /experiments/{id}) e os usuários
// e devolvem o documento Markdown, o resumo que vai para a IA e o pedido de e-mail. Só lê; não altera nada.
// Sigilo: evidência "Restrito ao parceiro" aparece no documento só como contagem e link, sem título; a IA recebe
// apenas dados agregados (sem textos, sem nomes de parceiros, sem títulos de evidências, marcos, desvios ou caderno).

function campos(x) {
  let m = x.metadata_decoded || x.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = {}; }
  }
  return (m && m.extra_fields) || {};
}

function valor(x, nome) {
  const c = campos(x)[nome];
  return c && c.value !== undefined && c.value !== null ? String(c.value).trim() : '';
}

function ligados(x, categorias) {
  const ids = new Map();
  for (const l of [...(x.items_links || []), ...(x.related_items_links || []),
    ...(x.experiments_links || []), ...(x.related_experiments_links || [])]) {
    if (l && categorias.includes(l.category_title)) ids.set(`${l.category_title}:${l.entityid}`, l);
  }
  return [...ids.values()];
}

const ISO = /^\d{4}-\d{2}-\d{2}$/;
const br = (iso) => (iso && ISO.test(iso) ? iso.split('-').reverse().join('/') : '');
const dia = (s) => String(s || '').slice(0, 10);

// Período padrão: o ano civil anterior à data de execução (o relatório de 15/01/2027 cobre 2026).
function periodoDe(cfg, hoje) {
  if (cfg.inicio || cfg.fim) {
    if (!ISO.test(cfg.inicio || '') || !ISO.test(cfg.fim || '') || cfg.inicio > cfg.fim) {
      throw new Error(`Período inválido: início "${cfg.inicio}" e fim "${cfg.fim}" devem estar em AAAA-MM-DD, com início antes do fim.`);
    }
    return { inicio: cfg.inicio, fim: cfg.fim };
  }
  const ano = hoje.getFullYear() - 1;
  return { inicio: `${ano}-01-01`, fim: `${ano}-12-31` };
}

// Texto de uma linha, seguro para Markdown (tabelas e listas).
function md(s) {
  return String(s ?? '').replace(/[\r\n]+/g, ' ').replace(/\|/g, '\\|').replace(/([*_`[\]<>])/g, '\\$1').trim();
}

function montarRelatorio({ recursos, experimentos, usuarios, cfg, hoje }) {
  const per = periodoDe(cfg, hoje);
  const c = cfg.categorias;
  const noPeriodo = (d) => Boolean(d) && d >= per.inicio && d <= per.fim;
  const url = (x) => `${cfg.urlPublica}/${x._tipo === 'exp' ? 'experiments' : 'database'}.php?mode=view&id=${x.id}`;
  const link = (x, texto) => `[${md(texto)}](${url(x)})`;
  const pessoa = new Map((usuarios || []).filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const nomeDe = (id) => { const p = pessoa.get(String(id)); return (p && p.fullname) || ''; };

  const itens = (recursos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'item' }));
  const exps = (experimentos || []).filter((x) => x && x.id !== undefined).map((x) => ({ ...x, _tipo: 'exp' }));
  const todos = [...itens, ...exps];

  const dataDe = (x) => {
    if (x.category_title === c.evidencia) return valor(x, cfg.campoDataEvidencia) || dia(x.date) || dia(x.created_at);
    if (x.category_title === c.marco) return valor(x, cfg.campoFimMarco) || dia(x.date) || dia(x.created_at);
    return dia(x.date) || dia(x.created_at);
  };

  const encerradas = [cfg.situacaoConcluido, cfg.situacaoSuspenso];
  const fichas = itens.filter((x) => x.category_title === c.ficha).filter((f) => {
    const inicio = valor(f, cfg.campoInicio) || dia(f.created_at);
    if (inicio && inicio > per.fim) return false;
    if (encerradas.includes(f.status_title) && dia(f.modified_at) < per.inicio) return false;
    return true;
  }).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
  const idsFichas = new Set(fichas.map((f) => String(f.id)));
  const fichasDe = (x) => ligados(x, [c.ficha]).map((l) => String(l.entityid));
  const doProjeto = (f) => todos.filter((x) => x.id !== f.id || x._tipo !== 'item').filter((x) => fichasDe(x).includes(String(f.id)));

  const registros = [c.plano, c.caderno, c.desvio, c.marco, c.evidencia, c.produto];
  const restrita = (x) => valor(x, cfg.campoSigilo) === cfg.sigiloRestrito;
  const publicado = (x) => valor(x, cfg.campoSituacaoProduto) === cfg.produtoPublicado;

  const linhas = [];
  const L = (s = '') => linhas.push(s);
  const projetosIA = [];
  const produtosTodos = [];
  const pontos = [];
  const pi = [];
  const porSituacao = new Map();
  const contagem = Object.fromEntries(registros.map((k) => [k, 0]));
  let restritas = 0;

  const secoes = [];
  fichas.forEach((f, i) => {
    const cod = `P${i + 1}`;
    porSituacao.set(f.status_title, (porSituacao.get(f.status_title) || 0) + 1);
    const ligadosAqui = doProjeto(f);
    const cat = (k) => ligadosAqui.filter((x) => x.category_title === k);
    const doPeriodo = (k) => cat(k).filter((x) => noPeriodo(dataDe(x)));
    const planos = cat(c.plano);
    const marcos = doPeriodo(c.marco).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const desvios = doPeriodo(c.desvio).sort((a, b) => dataDe(a).localeCompare(dataDe(b)));
    const cadernos = doPeriodo(c.caderno);
    const evidencias = doPeriodo(c.evidencia).sort((a, b) => String(a.title).localeCompare(String(b.title), 'pt-BR'));
    const produtos = cat(c.produto);
    for (const k of registros) contagem[k] += k === c.produto ? produtos.length : k === c.plano ? planos.length : doPeriodo(k).length;
    const nRestritas = evidencias.filter(restrita).length;
    restritas += nRestritas;

    const s = [];
    s.push(`### ${cod}. ${md(f.title)}`, '');
    s.push(`- Ficha: ${link(f, f.title)} — situação: **${md(f.status_title)}**`);
    const vinculo = valor(f, 'Vínculo');
    const parceiro = valor(f, 'Parceiro');
    s.push(`- Vínculo: ${md(vinculo) || 'não informado'}${parceiro ? `; parceiro ou financiador: ${md(parceiro)}` : ''}`);
    s.push(`- Pesquisador-líder: ${md(valor(f, 'Pesquisador-líder') || nomeDe(f.userid)) || 'não informado'}`);
    if (valor(f, 'Pesquisadores')) s.push(`- Pesquisadores: ${md(valor(f, 'Pesquisadores'))}`);
    if (valor(f, 'Colaboradores e orientador')) s.push(`- Colaboradores e orientador: ${md(valor(f, 'Colaboradores e orientador'))}`);
    const ini = valor(f, cfg.campoInicio);
    const fim = valor(f, cfg.campoTermino);
    s.push(`- Início: ${br(ini) || 'não informado'}; término previsto: ${br(fim) || 'não informado'}`);
    if (planos.length) {
      for (const p of planos) s.push(`- Plano: ${link(p, p.title)} (${md(p.status_title)}); abordagem: ${md(valor(p, 'Abordagem metodológica')) || 'não informada'}`);
    } else {
      s.push('- Plano: **sem plano de pesquisa ligado à ficha**');
    }
    s.push(`- No período: ${cadernos.length} entrada(s) de caderno, ${desvios.length} desvio(s), ${marcos.length} relatório(s) de marco, ${evidencias.length} evidência(s)${nRestritas ? ` (${nRestritas} restrita(s) ao parceiro)` : ''}.`);
    s.push('');
    if (marcos.length) {
      s.push('**Marcos no período**', '');
      marcos.forEach((m, j) => s.push(`- ${cod}-M${j + 1}. ${link(m, m.title)} — ${md(valor(m, 'Situação')) || 'situação não informada'}; período ${br(valor(m, 'Início do período')) || '?'} a ${br(valor(m, cfg.campoFimMarco)) || '?'}`));
      s.push('');
    }
    if (desvios.length) {
      s.push('**Desvios do plano no período**', '');
      desvios.forEach((d, j) => s.push(`- ${cod}-D${j + 1}. ${link(d, d.title)} — aspecto: ${md(valor(d, 'Aspecto alterado')) || 'não informado'}; ${br(dataDe(d))}`));
      s.push('');
    }
    if (produtos.length) {
      s.push('**Produtos**', '');
      produtos.forEach((p, j) => {
        const doi = valor(p, cfg.campoDoi);
        s.push(`- ${cod}-R${j + 1}. ${link(p, p.title)} — ${md(valor(p, 'Tipo de produto')) || 'tipo não informado'}; ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'}${doi ? `; ${md(doi)}` : ''}`);
        produtosTodos.push({ cod: `${cod}-R${j + 1}`, p, f, doi });
        if (publicado(p) && !doi) pontos.push(`${cod}-R${j + 1}. Produto publicado sem DOI ou endereço: ${link(p, p.title)}`);
        if (cfg.tiposPI.includes(valor(p, 'Tipo de produto'))) pi.push(`${cod}-R${j + 1}. ${link(p, p.title)} (${md(valor(p, 'Tipo de produto'))}, ${md(valor(p, cfg.campoSituacaoProduto)) || 'situação não informada'})`);
      });
      s.push('');
    }
    if (evidencias.length) {
      s.push('**Evidências no período**', '');
      evidencias.forEach((e) => {
        const quando = br(dataDe(e));
        s.push(restrita(e)
          ? `- ${link(e, 'Evidência restrita ao parceiro')} — ${quando}`
          : `- ${link(e, e.title)} — ${md(valor(e, 'Tipo')) || 'tipo não informado'}; ${md(valor(e, cfg.campoSigilo)) || 'sigilo não informado'}; ${quando}`);
      });
      s.push('');
    }
    const passoPI = (f.steps || []).find((st) => /propriedade intelectual/i.test(st.body || ''));
    if (passoPI) pi.push(`${cod}. ${link(f, f.title)}: avaliação de propriedade intelectual pelo Comitê ${Number(passoPI.finished) ? 'registrada como feita' : 'ainda não marcada na ficha'}`);
    if (fim && fim < dia(hoje.toISOString()) && f.status_title === cfg.situacaoAndamento) pontos.push(`${cod}. Término previsto (${br(fim)}) já passou e o projeto continua "${md(cfg.situacaoAndamento)}": ${link(f, f.title)}`);
    if (!planos.length) pontos.push(`${cod}. Sem plano de pesquisa ligado: ${link(f, f.title)}`);
    secoes.push(s.join('\n'));

    projetosIA.push({
      codigo: cod,
      titulo: f.title,
      situacao: f.status_title,
      vinculo: vinculo || 'não informado',
      inicio: ini || '',
      terminoPrevisto: fim || '',
      abordagem: planos.map((p) => valor(p, 'Abordagem metodológica')).filter(Boolean).join('; '),
      noPeriodo: { cadernos: cadernos.length, desvios: desvios.length, marcos: marcos.length, evidencias: evidencias.length },
      marcos: marcos.map((m, j) => ({ codigo: `${cod}-M${j + 1}`, situacao: valor(m, 'Situação'), inicio: valor(m, 'Início do período'), fim: valor(m, cfg.campoFimMarco) })),
      desvios: desvios.map((d, j) => ({ codigo: `${cod}-D${j + 1}`, aspecto: valor(d, 'Aspecto alterado') })),
      produtos: produtos.map((p, j) => ({ codigo: `${cod}-R${j + 1}`, tipo: valor(p, 'Tipo de produto'), situacao: valor(p, cfg.campoSituacaoProduto), ...(publicado(p) ? { titulo: p.title, doi: valor(p, cfg.campoDoi) } : {}) })),
    });
  });

  // registros do período sem ligação com nenhum projeto
  const soltos = todos.filter((x) => registros.includes(x.category_title) && !fichasDe(x).some((id) => idsFichas.has(id)) && noPeriodo(dataDe(x)));

  const ano = per.inicio.slice(0, 4) === per.fim.slice(0, 4) && per.inicio.endsWith('-01-01') && per.fim.endsWith('-12-31') ? per.inicio.slice(0, 4) : '';
  const rotuloPeriodo = ano || `${br(per.inicio)} a ${br(per.fim)}`;
  const agora = new Date(hoje.getTime() + cfg.fusoHoras * 3600e3).toISOString();
  L(`# Insumo para o relatório anual de PD&I — ${rotuloPeriodo}`);
  L();
  L(`*Gerado em ${br(agora.slice(0, 10))} às ${agora.slice(11, 16)} a partir do eLabFTW do Modal. Período: ${br(per.inicio)} a ${br(per.fim)}. Os links exigem entrada no eLabFTW. Este documento é a base para escrever a seção de PD&I; não é anexado ao relatório.*`);
  L();
  L('## 1. Resumo em números');
  L();
  L('| Indicador | Quantidade |');
  L('|---|---|');
  L(`| Projetos considerados | ${fichas.length} |`);
  for (const [sit, n] of [...porSituacao].sort()) L(`| Projetos ${md(sit).toLowerCase()} | ${n} |`);
  L(`| Entradas de caderno no período | ${contagem[c.caderno]} |`);
  L(`| Desvios do plano no período | ${contagem[c.desvio]} |`);
  L(`| Relatórios de marco no período | ${contagem[c.marco]} |`);
  L(`| Evidências no período | ${contagem[c.evidencia]}${restritas ? ` (${restritas} restrita(s) ao parceiro)` : ''} |`);
  L(`| Produtos ligados aos projetos | ${contagem[c.produto]} (${produtosTodos.filter((x) => publicado(x.p)).length} publicados) |`);
  L(`| Registros do período sem ligação com projeto | ${soltos.length} |`);
  L();
  L('## 2. Texto de contexto (rascunho gerado por IA)');
  L();
  L('> **Rascunho para revisão.** Texto escrito por IA a partir dos dados agregados abaixo, sem conteúdo restrito ao parceiro, sem textos dos registros e sem o campo de parceiro (o título do projeto vai como está). Cada afirmação cita o código do registro (P1, P1-M1, P1-R1...). Confira antes de usar.');
  L();
  L('{{TEXTO_IA}}');
  L();
  L('## 3. Projetos');
  L();
  if (secoes.length) secoes.forEach((s) => { L(s); L(); });
  else { L('Nenhum projeto no período.'); L(); }
  L('## 4. Produtos e DOIs');
  L();
  if (produtosTodos.length) {
    L('| Código | Produto | Tipo | Situação | DOI ou endereço | Projeto |');
    L('|---|---|---|---|---|---|');
    for (const { cod, p, f, doi } of produtosTodos) L(`| ${cod} | ${link(p, p.title)} | ${md(valor(p, 'Tipo de produto'))} | ${md(valor(p, cfg.campoSituacaoProduto))} | ${md(doi)} | ${md(f.title)} |`);
  } else {
    L('Nenhum produto ligado aos projetos.');
  }
  L();
  L('## 5. Propriedade intelectual');
  L();
  if (pi.length) pi.forEach((x) => L(`- ${x}`));
  else L('Nenhum produto de propriedade intelectual nem avaliação registrada.');
  L();
  L('## 6. Pontos de atenção');
  L();
  if (pontos.length || soltos.length) {
    pontos.forEach((x) => L(`- ${x}`));
    if (soltos.length) {
      L(`- ${soltos.length} registro(s) do período sem ligação com a ficha de um projeto:`);
      soltos.forEach((x) => L(`  - ${restrita(x) ? link(x, 'Evidência restrita ao parceiro') : link(x, x.title)} (${md(x.category_title)}, ${md(nomeDe(x.userid)) || 'dono não identificado'})`));
    }
  } else {
    L('Nenhum.');
  }
  L();

  const resumoIA = {
    periodo: { inicio: per.inicio, fim: per.fim },
    totais: {
      projetos: fichas.length,
      projetosPorSituacao: Object.fromEntries(porSituacao),
      cadernos: contagem[c.caderno], desvios: contagem[c.desvio], marcos: contagem[c.marco],
      evidencias: contagem[c.evidencia], produtos: contagem[c.produto],
    },
    projetos: projetosIA,
  };
  return { periodo: per, rotuloPeriodo, markdown: linhas.join('\n'), resumoIA, totais: resumoIA.totais, pontos: pontos.length + soltos.length };
}

function promptIA(resumoIA) {
  return [
    'Você ajuda o Comitê de PD&I do Instituto Modal (instituto de ciência e tecnologia, Brasil) a escrever a seção de PD&I do relatório anual.',
    'Escreva em português do Brasil, em prosa corrida, de um a quatro parágrafos curtos (menos dados, menos texto), um texto de contexto sobre as atividades de pesquisa aplicada do período, com base SOMENTE nos dados JSON abaixo.',
    'Regras:',
    '- Toda afirmação sobre um projeto, marco, desvio ou produto cita o código entre colchetes, por exemplo [P1] ou [P1-R2].',
    '- Use só o que está nos dados. Não invente nem deduza resultados, números, nomes, organizações, parceiros, impactos ou expectativas futuras.',
    '- Não diga que um projeto está no prazo, atrasado ou dentro do cronograma, a menos que um marco traga essa situação. Ausência de marcos ou desvios não significa nada: não a interprete.',
    '- Não qualifique registros (por exemplo, "evidências fundamentais", "produto significativo") nem diga para que servem.',
    '- Não escreva frases genéricas sobre pesquisa, metodologia, boas práticas ou o que um tipo de registro costuma ser. Cada frase deve conter um fato dos dados.',
    '- Não comente a ausência de dados. Se não houve marcos ou desvios, simplesmente não fale deles.',
    '- Não mencione o nome de parceiros ou empresas; o vínculo ("Projeto com parceiro", "Fomento externo") pode ser citado.',
    '- Não use títulos, listas, tabelas nem HTML; só parágrafos de texto simples.',
    '- Tom institucional e sóbrio, sem adjetivos promocionais.',
    '- Quando houver desvios ou marcos com atraso, mencione-os com naturalidade, como parte do processo de pesquisa.',
    '',
    'Dados:',
    JSON.stringify(resumoIA, null, 1),
  ].join('\n');
}

// Junta o texto da IA ao documento. A IA não é confiável: o texto vira parágrafos simples, sem HTML nem Markdown ativo.
function finalizarDocumento(markdown, textoIA) {
  const limpo = String(textoIA || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/^#+\s*/gm, '')
    .replace(/[ \t]+/g, ' ')
    .split(/\n\s*\n/)
    .map((p) => p.replace(/\s*\n\s*/g, ' ').trim())
    .filter(Boolean)
    .join('\n\n');
  const texto = limpo || '*O texto de contexto não foi gerado nesta execução (falha ou resposta vazia da IA). O restante do documento está completo.*';
  return markdown.replace('{{TEXTO_IA}}', () => texto);
}

function pedidoEmail({ rel, usuarios, cfg }) {
  const testador = (usuarios || []).find((u) => u && String(u.userid) === String(cfg.usuarioTesteId));
  if (cfg.modoTeste && !(testador && testador.email)) {
    throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi enviado.`);
  }
  const t = rel.totais;
  const blocos = [
    { tipo: 'paragrafo', texto: `Segue em anexo o insumo para a seção de PD&I do relatório anual (${rel.rotuloPeriodo}), gerado a partir do eLabFTW. É um documento Markdown, com links para os registros (os links exigem entrada no eLabFTW).` },
    { tipo: 'lista', itens: [
      { texto: `${t.projetos} projeto(s) considerado(s)` },
      { texto: `${t.cadernos} entrada(s) de caderno, ${t.desvios} desvio(s) e ${t.marcos} relatório(s) de marco no período` },
      { texto: `${t.evidencias} evidência(s) no período e ${t.produtos} produto(s) ligados aos projetos` },
      { texto: `${rel.pontos} ponto(s) de atenção (seção 6 do documento)` },
    ] },
    { tipo: 'paragrafo', texto: 'A seção 2 traz um texto de contexto escrito por IA, marcado como rascunho: confira cada afirmação pelos códigos citados antes de usar. A IA não recebeu conteúdo restrito ao parceiro, textos dos registros nem o campo de parceiro.' },
  ];
  if (cfg.modoTeste) blocos.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este e-mail iria para ${cfg.para}${cfg.copia ? `, com cópia para ${cfg.copia}` : ''}.` });
  return {
    para: cfg.modoTeste ? testador.email : cfg.para,
    cc: cfg.modoTeste ? '' : cfg.copia,
    nomeRemetente: 'PD&I Modal',
    responderPara: 'pesquisa@modal.org.br',
    assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    etiqueta: 'eLabFTW · Relatório anual',
    titulo: `Insumo para o relatório anual de PD&I — ${rel.rotuloPeriodo}`,
    blocos,
    acaoRotulo: 'Abrir o eLabFTW',
    acaoUrl: cfg.urlPublica,
    rodape: 'Gerado automaticamente a partir do eLabFTW do Modal. Dúvidas: pesquisa@modal.org.br.',
    anexos: 'relatorio',
  };
}

function nomeArquivo(rel) {
  return `insumo-relatorio-pdi-${rel.periodo.inicio}-a-${rel.periodo.fim}.md`;
}


const cfg = $('Configuração').first().json;
const rel = $('Montar documento').first().json;
const ia = $input.first().json;
const markdown = finalizarDocumento(rel.markdown, ia && typeof ia.text === 'string' ? ia.text : '');
const pedido = pedidoEmail({ rel, usuarios: $('Ler usuários').all().map((i) => i.json), cfg });
const arquivo = await this.helpers.prepareBinaryData(Buffer.from(markdown, 'utf8'), nomeArquivo(rel), 'text/markdown');
return [{ json: pedido, binary: { relatorio: arquivo } }];
